import { Bar } from "@nivo/bar";
import SizedChart from "../../organisms/SizedChart.js";
import { Box, Typography } from "@mui/material";

import { NIVO_THEME } from "../../../AppTheme.js";
import { getMarkColor } from "../../../nonview/constants/COLORS.js";
import {
  CHART_MIN_CATEGORY_WIDTH,
  CHART_HORIZONTAL_MARGIN,
} from "../../../nonview/constants/ChartLabels.js";
import {
  BAR_CHART_MIN_HEIGHT_PX,
  getDenseAxisTheme,
  getSlantedXAxis,
  X_AXIS_BOTTOM_MARGIN,
} from "../visual_utils/ChartAxisUtils.js";
import FormatUtils from "../visual_utils/FormatUtils.js";
import InBarLabels from "./InBarLabels.js";

export default function BarChart({ data, xAxisLabel, yAxisLabel }) {
  return (
    <Box sx={{ width: "100%", height: BAR_CHART_MIN_HEIGHT_PX }}>
      <SizedChart
        chart={Bar}
        minWidth={
          new Set(data.map(({ id }) => id)).size * CHART_MIN_CATEGORY_WIDTH +
          CHART_HORIZONTAL_MARGIN
        }
        theme={getDenseAxisTheme(NIVO_THEME, data.length)}
        data={data}
        keys={["value"]}
        indexBy="id"
        animate={false}
        margin={{ top: 50, right: 50, bottom: X_AXIS_BOTTOM_MARGIN, left: 70 }}
        padding={0.3}
        valueScale={{ type: "linear" }}
        colors={(bar) => getMarkColor(bar.data.color)}
        axisLeft={{
          format: FormatUtils.humanizeValue,
          tickSize: 5,
          tickPadding: 5,
          tickRotation: 0,
          legend: yAxisLabel,
          legendPosition: "middle",
          legendOffset: -50,
        }}
        label={({ value }) => FormatUtils.humanizeValue(value)}
        enableLabel={false}
        layers={[
          "grid",
          "axes",
          "bars",
          InBarLabels,
          "totals",
          "markers",
          "legends",
          "annotations",
        ]}
        tooltip={({ value, indexValue }) => (
          <Typography variant="body2">
            {indexValue}: {FormatUtils.humanizeValue(value)}
          </Typography>
        )}
        axisBottom={getSlantedXAxis(xAxisLabel)}
        role="img"
        ariaLabel="Bar chart"
      />
    </Box>
  );
}

BarChart.IS_CHART = true;
BarChart.IS_FULL_WIDTH = true;
